-- Italy deep-dive content: page, stats, file_format cards, 3 scope_transmission cards
-- + 1 lifecycle card (the static page's clearance-workflow .flow-grid, embedded inside a
-- spec-card with both intro_text and outro_text -- mapped onto deep_dive_lifecycle_cards
-- per established precedent), steps, 2 penalty rows (genuine tabular penalty schedule)
-- PLUS 3 narrative penalties_related cards -- confirms a country can have both at once,
-- per the Belgium precedent. 2 portals.

INSERT OR IGNORE INTO deep_dive_pages (country_id, last_updated) SELECT id, '2026-07-21' FROM countries WHERE name_en = 'Italy';
INSERT OR IGNORE INTO deep_dive_page_translations (country_id, lang, compliance_model, footer_disclaimer, timeline_intro, file_format_intro, scope_intro, steps_intro, penalties_intro) SELECT id, 'en', 'Centralised clearance (SDI) — since 2014', 'This deep-dive page reflects publicly available technical guidance as of July 2026 and is provided for general awareness, not legal or tax advice. FatturaPA schema versions, rejection codes, and penalty calculations continue to evolve — confirm current requirements directly on the Agenzia delle Entrate''s portal before building an integration.', 'Italy has the longest continuous track record of any e-invoicing regime in the EU — the interesting news today is schema maintenance, not a new mandate.', 'FatturaPA predates EN 16931 entirely — it''s Italy''s own schema, not a national implementation of the European standard.', 'SDI is a true clearinghouse: an invoice sent directly to a buyer, bypassing SDI, simply has no legal validity in Italy.', 'Since Italy''s system has run for over a decade, most of the "registration" work is really about choosing the right channel and getting the technical detail right.', 'Italy separates substantive VAT violations from purely formal ones — the two carry very different consequences.' FROM countries WHERE name_en = 'Italy';

