INSERT OR IGNORE INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'file_format', 0 FROM countries WHERE name_en = 'Italy';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'en', 'Schema', '[["Format", "FatturaPA XML — Italy''s own schema"], ["Relationship to EN 16931", "Predates it; not a CIUS implementation"], ["Current version", "1.9.1 (mandatory from 15 May 2026)"], ["Field count", "100+ mandatory and optional data fields"]]', 'Don''t assume EN 16931 tooling built for France, Germany, or Poland will map cleanly onto FatturaPA — the schema has its own lineage and its own rules.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries co ON co.id = dc.country_id WHERE co.name_en = 'Italy' AND dc.section = 'file_format' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'file_format', 1 FROM countries WHERE name_en = 'Italy';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'en', 'Document structure', '[["Root element", "<FatturaElettronica>"], ["Header block", "FatturaElettronicaHeader (routing + parties)"], ["Party fields", "CedentePrestatore (seller), CessionarioCommittente (buyer)"], ["Key identifiers", "Codice Fiscale, Partita IVA"]]', 'The most common rejection cause across every source on FatturaPA is the same: an invalid Codice Fiscale or Partita IVA on either party. Validate these before anything else.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries co ON co.id = dc.country_id WHERE co.name_en = 'Italy' AND dc.section = 'file_format' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'file_format', 2 FROM countries WHERE name_en = 'Italy';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'en', 'Digital signature', '[["Required format", "XAdES or CAdES (.p7m)"], ["Applies to", "Every invoice, without exception"], ["File naming", "IT + VAT number + _ + progressive number"]]', 'Unlike Poland''s KSeF or Croatia''s fiscalisation model, Italy requires the invoice XML itself to be digitally signed — this sits at the document level, not just the transport layer.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries co ON co.id = dc.country_id WHERE co.name_en = 'Italy' AND dc.section = 'file_format' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'file_format', 3 FROM countries WHERE name_en = 'Italy';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'en', 'Archiving', '[["Retention period", "10 years — \"conservazione sostitutiva\""], ["Applies to", "Both issuer and recipient"]]', '"Conservazione sostitutiva" (digital preservation) is a distinct legal regime from simple file storage — it has its own integrity and accessibility requirements under Italian law.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries co ON co.id = dc.country_id WHERE co.name_en = 'Italy' AND dc.section = 'file_format' AND dc.sort_order = 3;

INSERT OR IGNORE INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'scope_transmission', 0 FROM countries WHERE name_en = 'Italy';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'en', 'Routing identifiers', '[["Primary", "Codice Destinatario (7-character code)"], ["Fallback", "PEC (certified email) address"], ["If neither known", "Code set to 0000000, PEC used instead"], ["If both present", "SDI uses Codice Destinatario, ignores PEC"]]', 'Non-Italian companies typically obtain a Codice Destinatario through an intermediary or their ERP''s SDI connectivity module, rather than registering directly with the Agenzia delle Entrate.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries co ON co.id = dc.country_id WHERE co.name_en = 'Italy' AND dc.section = 'scope_transmission' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'scope_transmission', 1 FROM countries WHERE name_en = 'Italy';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'en', 'Transmission channels', '[["Options", "PEC, web upload, SFTP, SDICoop web services"], ["Success receipt", "Ricevuta di Consegna (delivery receipt)"], ["Failure receipt", "Notifica di Scarto (rejection, with error code)"]]', 'Build your pipeline to handle both receipt types explicitly — a Notifica di Scarto means the invoice was never legally issued at all, not just delayed.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries co ON co.id = dc.country_id WHERE co.name_en = 'Italy' AND dc.section = 'scope_transmission' AND dc.sort_order = 1;
