INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'en', 'Cross-border reporting', '[["TD17", "Services purchased from abroad"], ["TD18", "Goods purchased from the EU"], ["TD19", "Goods purchased from outside the EU"], ["Deadline", "Within 12 days"]]', 'These document types absorbed the old standalone "Esterometro" reporting system — it''s now fully integrated into SDI rather than a separate filing.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries co ON co.id = dc.country_id WHERE co.name_en = 'Italy' AND dc.section = 'scope_transmission' AND dc.sort_order = 2;

